    "image": "https://miro.medium.com/v2/resize:fit:2000/format:webp/1*JXgOF-w_gIDA7L2EAXP7iw.png",
    "permalink": "/blog/simulating-a-banking-security-infrastructure-part-1/",
    "url": "/blog/simulating-a-banking-security-infrastructure-part-1/",
